// Actual group form: local destination, retained creation and invitation recovery.
const assert=require('node:assert/strict'),fs=require('node:fs'),os=require('node:os'),path=require('node:path'),http=require('node:http');
const {execFileSync}=require('node:child_process'),{chromium}=require(process.env.AGENTNET_PLAYWRIGHT);
const web=path.resolve(__dirname,'../web'),work=fs.mkdtempSync(path.join(os.tmpdir(),'agentnet-new-group-'));
const entry=`
import React,{useState} from 'react';import {createRoot} from 'react-dom/client';
import {Store} from './src/store';import {StoreContext} from './src/context';import {OwnedContext} from './src/owned';
import {NewGroupForm} from './src/features/NewChat';import {Sheet} from './src/ui/Sheet';
const root=document.getElementById('root'),app=document.getElementById('app'),portals=document.getElementById('portals'),navigate=new URL(location).searchParams.get('navigate')==='true';
const people=['Bob','Carol'].map(n=>({person:n.toLowerCase(),label:'Fixture '+n,state:'pinned',address:n.toLowerCase()+'/laptop',devices:[]}));
const overview={seq:1,version:'fixture',role:'person',groups:true,persons:true,me:{address:'self/laptop'},person:{person:'self',label:'Fixture owner',state:'self',address:'self/laptop',devices:[]},people,dms:[],threads:[],needs_you:[]};
const f=window.fixture={creates:[],invites:[],created:[],reads:[],holdReads:false};
const thread=id=>({id,kind:'group',title:'Fixture new group',role:'member',members:[{...overview.person,admin:true}],peer:{label:'Fixture group'},messages:[],agents:[],guests:[],topics:[]});
const host={platform:'daemon',workspace:{id:'new-group',state:'enrolled'},listen(){return()=>{}},async api(p,b){
 if(p.startsWith('/api/overview'))return structuredClone(overview);
 if(p==='/api/groups/new')return new Promise((resolve,reject)=>f.creates.push({b,resolve,reject}));
 if(p==='/api/groups/invite')return new Promise((resolve,reject)=>f.invites.push({b,resolve,reject}));
 if(p.startsWith('/api/dm?')){const t=thread(new URL(p,location.href).searchParams.get('id'));if(f.holdReads)return new Promise(resolve=>f.reads.push(()=>resolve(t)));return t}
 if(p==='/api/refresh'||p==='/api/topic/transfer/location')return {};
 if(p.includes('/groups/invitations'))return [];
 if(p==='/api/teams')return {status:'available',current:true,teams:[]};
 if(p.startsWith('/api/agents'))return {agents:[]};
 if(b)throw Error('Unexpected fixture mutation '+p);return {};
}};
const store=new Store(host);f.store=store;
f.finishCreate=(index,fail=false)=>{const w=f.creates[index];if(fail){w.reject(Error('Invented creation refusal'));return}const id='created-group-'+index;overview.dms.push({id,kind:'group',title:w.b.title,role:'member'});overview.seq++;w.resolve({id})};
f.finishInvite=(index,fail=false)=>{const w=f.invites[index];if(fail)w.reject(Error('Invented invitation refusal'));else w.resolve({note:'invited'})};
f.owner=async()=>{overview.person={...overview.person,person:'other-owner'};overview.seq++;await store.refetch()};
function App(){const [mounted,setMounted]=useState(true);return <><textarea aria-label="Unrelated draft"/>{mounted?<Sheet open title="New group" onOpenChange={v=>{if(!v)setMounted(false)}}><NewGroupForm navigate={navigate} initialPeople={[{id:'bob'},{id:'carol'}]} onBack={()=>setMounted(false)} onCreated={id=>{f.created.push(id);setMounted(false)}}/></Sheet>:<button onClick={()=>setMounted(true)}>Reopen group creation</button>}</>}
await store.start();createRoot(app).render(<OwnedContext.Provider value={{root,app,portals}}><StoreContext.Provider value={store}><App/></StoreContext.Provider></OwnedContext.Provider>);
`;
const aliases={'optimistic.mjs':'static/optimistic.mjs','pictures.mjs':'static/pictures.mjs','person-topics.mjs':'skins/shared/person-topics.mjs','reaction-preferences.mjs':'skins/shared/reaction-preferences.mjs','collective-mentions.mjs':'skins/shared/collective-mentions.mjs','drive-space.mjs':'skins/shared/drivespace.mjs','drive-setup.mjs':'skins/shared/drivespace-setup.mjs'};
fs.cpSync(path.join(web,'src'),path.join(work,'src'),{recursive:true});
if(process.env.AGENTNET_NEW_GROUP_SOURCE)fs.copyFileSync(process.env.AGENTNET_NEW_GROUP_SOURCE,path.join(work,'src/features/NewChat.tsx'));
for(const [a,b] of Object.entries(aliases))fs.copyFileSync(path.resolve(web,'../',b),path.join(work,'src',a));
fs.symlinkSync(path.join(web,'node_modules'),path.join(work,'node_modules'),'dir');
const js=require(path.join(web,'node_modules/esbuild')).buildSync({stdin:{contents:entry,resolveDir:work,loader:'tsx'},bundle:true,format:'esm',target:'es2022',jsx:'automatic',define:{'process.env.NODE_ENV':'"production"'},write:false}).outputFiles[0].text;
execFileSync(process.execPath,[path.join(web,'node_modules/@tailwindcss/cli/dist/index.mjs'),'-i',path.join(work,'src/styles.css'),'-o',path.join(work,'style.css'),'--minify'],{cwd:work,stdio:'pipe'});
const css=fs.readFileSync(path.join(work,'style.css'));
const server=http.createServer((req,res)=>{if(req.url==='/entry.mjs'){res.setHeader('Content-Type','text/javascript');return res.end(js)}if(req.url==='/style.css'){res.setHeader('Content-Type','text/css');return res.end(css)}res.setHeader('Content-Type','text/html');res.end('<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><title>Group creation fixture</title><link rel="icon" href="data:,"><link rel="stylesheet" href="/style.css"><div id="root" class="an-root"><div id="app" class="an-app"></div><div id="portals"></div></div><script type="module" src="/entry.mjs"></script>')});
(async()=>{let browser;const reports=[];try{
 await new Promise(r=>server.listen(0,'127.0.0.1',r));browser=await chromium.launch({headless:true});
 const setup=async(page,navigate=true)=>{page.setDefaultTimeout(5000);await page.goto('http://127.0.0.1:'+server.address().port+'/?navigate='+navigate);await page.getByRole('textbox',{name:'Group name',exact:true}).fill('Fixture new group')};
 const region=page=>page.getByRole('region',{name:'Creating group “Fixture new group”',exact:true});
 const start=async page=>{const button=page.getByRole('button',{name:'Create group',exact:true});await button.scrollIntoViewIfNeeded();await button.evaluate(b=>b.addEventListener('click',e=>fixture.input={at:performance.now(),trusted:e.isTrusted},{once:true,capture:true}));await button.click();await region(page).waitFor({timeout:500})};
 const capture=async(page,name)=>{if(!process.env.AGENTNET_NEW_GROUP_EVIDENCE)return;await page.evaluate(async()=>Promise.all(document.getAnimations().filter(a=>Number.isFinite(a.effect?.getComputedTiming().endTime)).map(a=>a.finished.catch(()=>{}))));await page.screenshot({path:process.env.AGENTNET_NEW_GROUP_EVIDENCE+'-'+name+'.png',fullPage:true})};
 for(const width of [1440,390])for(const navigate of [true,false]){
  const page=await browser.newPage({viewport:{width,height:960}}),errors=[];page.on('pageerror',e=>errors.push(String(e)));await setup(page,navigate);await start(page);const pending=region(page);const timing=await page.evaluate(async()=>{await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));return {...fixture.input,feedbackMs:performance.now()-fixture.input.at}});assert(timing.trusted&&timing.feedbackMs<500,JSON.stringify(timing));assert(await pending.evaluate(el=>{const r=el.getBoundingClientRect();let top=0,bottom=innerHeight;for(let p=el.parentElement;p;p=p.parentElement)if(/auto|scroll|hidden|clip/.test(getComputedStyle(p).overflowY)){const b=p.getBoundingClientRect();top=Math.max(top,b.top);bottom=Math.min(bottom,b.bottom)}return r.top>=top-1&&r.bottom<=bottom+1&&r.left>=0&&r.right<=innerWidth}),'pending destination inside viewport and scrollport');assert.equal(await page.evaluate(()=>fixture.store.hasUnsent()),true);assert.equal(await page.getByRole('textbox',{name:'Group name',exact:true}).count(),0);assert.equal(await page.evaluate(()=>fixture.store.get().open),null);assert.equal(await page.evaluate(()=>{const a=fixture.store.createGroup('Fixture new group',['bob','carol']),b=fixture.store.createGroup('Fixture new group',['bob','carol']);a.catch(()=>{});b.catch(()=>{});return a===b}),true);await capture(page,'pending-'+navigate+'-'+width);
  await pending.getByRole('button',{name:'Back to people',exact:true}).click();await page.getByRole('textbox',{name:'Unrelated draft'}).fill('Keep this draft');await page.getByRole('button',{name:'Reopen group creation',exact:true}).click();await pending.waitFor();assert.equal(await page.evaluate(()=>fixture.creates.length),1);
  await page.evaluate(()=>fixture.finishCreate(0));await page.waitForFunction(()=>fixture.invites.length===1);await pending.getByText('Group created. Sending invitations…',{exact:true}).waitFor();await page.evaluate(()=>fixture.finishInvite(0,true));await pending.getByRole('alert').waitFor();assert.equal(await page.evaluate(()=>fixture.store.hasUnsent()),false);await capture(page,'error-'+navigate+'-'+width);
  await pending.getByRole('button',{name:'Retry remaining invitations',exact:true}).click();await page.waitForFunction(()=>fixture.invites.length===2);await page.evaluate(()=>fixture.finishInvite(1));await page.waitForFunction(()=>fixture.invites.length===3);assert.deepEqual(await page.evaluate(()=>fixture.invites.map(w=>w.b.person)),['bob','bob','carol']);assert.equal(await page.evaluate(()=>fixture.creates.length),1);assert.equal(await pending.getByText('Fixture Bob',{exact:true}).count(),0,'confirmed invitation removed from remaining list');
  await page.getByRole('button',{name:'Close',exact:true}).click();await page.getByRole('button',{name:'Reopen group creation',exact:true}).click();await pending.waitFor();await page.evaluate(()=>fixture.finishInvite(2));await pending.getByText('Group created. Invitations sent; each person decides whether to join.',{exact:true}).waitFor();assert.deepEqual(await page.evaluate(()=>fixture.created),[],'late completion cannot invoke a closed form callback');assert.equal(await page.evaluate(()=>fixture.store.get().open),null);assert.equal(await page.evaluate(()=>fixture.store.hasUnsent()),false);await capture(page,'ready-'+navigate+'-'+width);
  if(navigate)await page.evaluate(()=>fixture.holdReads=true);await pending.getByRole('button',{name:'Open created group',exact:true}).click();assert.deepEqual(await page.evaluate(()=>fixture.created),['created-group-0']);if(navigate){await page.waitForFunction(()=>fixture.reads.length>0);await page.evaluate(()=>fixture.store.showTab('settings'));await page.evaluate(()=>fixture.reads.splice(0).forEach(r=>r()));await page.waitForTimeout(40);assert.equal(await page.evaluate(()=>fixture.store.get().invite),null,'late group load cannot open invitation over newer navigation')}else assert.equal(await page.evaluate(()=>fixture.store.get().open),null,'destination mode does not navigate');assert.equal(await page.getByRole('textbox',{name:'Unrelated draft'}).inputValue(),'Keep this draft');assert.deepEqual(errors,[]);reports.push({width,navigate,feedbackMs:timing.feedbackMs});await page.close();
 }
 for(const stage of ['create','invite'])for(const scope of ['owner','navigation','close','stopped']){
  const page=await browser.newPage({viewport:{width:390,height:960}});await setup(page);await start(page);if(stage==='invite'){await page.evaluate(()=>fixture.finishCreate(0));await page.waitForFunction(()=>fixture.invites.length===1)}
  if(scope==='owner')await page.evaluate(()=>fixture.owner());if(scope==='navigation')await page.evaluate(()=>fixture.store.showTab('settings'));if(scope==='close'){await page.getByRole('button',{name:'Close',exact:true}).click();await page.getByRole('button',{name:'Reopen group creation',exact:true}).waitFor()}if(scope==='stopped')await page.evaluate(()=>fixture.store.stop());
  if(stage==='create')await page.evaluate(()=>fixture.finishCreate(0));else await page.evaluate(()=>fixture.finishInvite(0));await page.waitForTimeout(40);
  if(['owner','stopped'].includes(scope))assert.equal(await page.evaluate(()=>fixture.invites.length),stage==='create'?0:1,'changed authority stops subsequent invitations');else{if(stage==='create'){await page.waitForFunction(()=>fixture.invites.length===1);await page.evaluate(()=>fixture.finishInvite(0))}await page.waitForFunction(()=>fixture.invites.length===2);await page.evaluate(()=>fixture.finishInvite(1));await page.waitForTimeout(40)}
  assert.deepEqual(await page.evaluate(()=>fixture.created),[],'late '+scope+' result cannot invoke callbacks');assert.equal(await page.evaluate(()=>fixture.store.get().open),null);assert.equal(await page.evaluate(()=>fixture.store.get().invite),null);await page.close();
 }
 {
  const page=await browser.newPage({viewport:{width:390,height:960}});await setup(page);await start(page);await page.evaluate(()=>fixture.finishCreate(0,true));await region(page).getByRole('alert').waitFor();await region(page).getByText('A group may already exist. Check Chats before trying creation again.',{exact:true}).waitFor();await region(page).getByRole('button',{name:'Try creating this group again',exact:true}).click();await page.waitForFunction(()=>fixture.creates.length===2);await page.evaluate(()=>fixture.finishCreate(1));await page.waitForFunction(()=>fixture.invites.length===1);await page.evaluate(()=>fixture.finishInvite(0));await page.waitForFunction(()=>fixture.invites.length===2);await page.evaluate(()=>fixture.finishInvite(1));await page.waitForFunction(()=>fixture.created.length===1&&fixture.store.get().invite?.conv==='created-group-1');assert.deepEqual(await page.evaluate(()=>fixture.created),['created-group-1']);await page.close();
 }
 for(const recovery of ['details','use-partial','another']){
  const page=await browser.newPage({viewport:{width:390,height:960}});await setup(page,false);await start(page);
  if(recovery==='details'){
   await page.evaluate(()=>fixture.finishCreate(0,true));await region(page).getByRole('button',{name:'Back to group details',exact:true}).click();assert.equal(await page.getByRole('textbox',{name:'Group name',exact:true}).inputValue(),'Fixture new group');await page.getByRole('alert').filter({hasText:'Check Chats before starting another group.'}).waitFor();assert.equal(await page.getByRole('checkbox',{name:'Fixture Bob',exact:true}).isChecked(),true);assert.equal(await page.evaluate(()=>fixture.creates.length),1);
  }else{
   await region(page).getByRole('button',{name:'Back to people',exact:true}).click();await page.evaluate(()=>fixture.finishCreate(0));await page.waitForFunction(()=>fixture.invites.length===1);await page.evaluate(fail=>fixture.finishInvite(0,fail),recovery==='use-partial');
   if(recovery==='another'){await page.waitForFunction(()=>fixture.invites.length===2);await page.evaluate(()=>fixture.finishInvite(1))}
   await page.getByRole('button',{name:'Reopen group creation',exact:true}).click();
   if(recovery==='use-partial'){await region(page).getByRole('button',{name:'Use group without remaining invitations',exact:true}).click();assert.deepEqual(await page.evaluate(()=>fixture.created),['created-group-0']);assert.equal(await page.evaluate(()=>fixture.invites.length),1)}
   else{await region(page).getByRole('button',{name:'Start another group',exact:true}).click();await page.getByRole('textbox',{name:'Group name',exact:true}).waitFor();assert.equal(await page.evaluate(()=>fixture.creates.length),1);await page.getByRole('textbox',{name:'Group name',exact:true}).fill('Another explicit group');await page.getByRole('button',{name:'Create group',exact:true}).click();await page.waitForFunction(()=>fixture.creates.length===2);assert.deepEqual(await page.evaluate(()=>fixture.creates.map(x=>x.b.title)),['Fixture new group','Another explicit group'])}
  }
  await page.close();
 }
 console.log(JSON.stringify({ok:true,reports,scope:'actual NewGroupForm, held creation and invites, Back/Close/reopen with retained remaining people, duplicate input, explicit retries, guarded callbacks/navigation, owner/stop boundaries; synthetic native transport'}));
 }finally{await browser?.close();await new Promise(r=>server.close(r));fs.rmSync(work,{recursive:true,force:true})}
})().catch(e=>{console.error(e.stack);process.exitCode=1});
